create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, timezone text not null default 'America/Argentina/Buenos_Aires');
create table public.memberships (organization_id uuid references public.organizations on delete cascade, user_id uuid references auth.users on delete cascade, role text not null check(role in ('admin','commercial')), active boolean not null default true, primary key(organization_id,user_id));
create function public.member_role(org uuid) returns text language sql stable security definer set search_path = '' as $$ select role from public.memberships where organization_id=org and user_id=auth.uid() and active $$;
revoke all on function public.member_role(uuid) from public;
grant execute on function public.member_role(uuid) to authenticated;
create table public.companies (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, name text not null check(length(trim(name)) between 1 and 160), source text not null default '', owner_id uuid not null default auth.uid(), created_at timestamptz not null default now(), unique(organization_id,id), foreign key(organization_id,owner_id) references public.memberships(organization_id,user_id));
create table public.stages (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, name text not null, position integer not null, unique(organization_id,id));
create table public.opportunities (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, company_id uuid not null, stage_id uuid not null, title text not null check(length(trim(title)) between 1 and 160), owner_id uuid not null default auth.uid(), status text not null default 'open' check(status in ('open','won','lost')), created_at timestamptz not null default now(), unique(organization_id,id), foreign key(organization_id,company_id) references public.companies(organization_id,id), foreign key(organization_id,stage_id) references public.stages(organization_id,id), foreign key(organization_id,owner_id) references public.memberships(organization_id,user_id));
create table public.activities (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, opportunity_id uuid not null, owner_id uuid not null default auth.uid(), kind text not null check(kind in ('call','followup','meeting','task')), title text not null check(length(trim(title)) between 1 and 200), notes text not null default '' check(length(notes)<=5000), due_at timestamptz not null, completed_at timestamptz, request_id uuid, created_at timestamptz not null default now(), unique(organization_id,request_id,kind), foreign key(organization_id,opportunity_id) references public.opportunities(organization_id,id), foreign key(organization_id,owner_id) references public.memberships(organization_id,user_id));
create table public.feedback (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, author_id uuid not null default auth.uid(), kind text not null check(kind in ('error','suggestion')), description text not null check(length(trim(description)) between 1 and 3000), created_at timestamptz not null default now(), foreign key(organization_id,author_id) references public.memberships(organization_id,user_id));
create index activities_pending on public.activities(organization_id,owner_id,due_at) where completed_at is null;
create index opportunities_company on public.opportunities(organization_id,company_id);
alter table public.organizations enable row level security;
alter table public.memberships enable row level security;
alter table public.stages enable row level security;
alter table public.companies enable row level security;
alter table public.opportunities enable row level security;
alter table public.activities enable row level security;
alter table public.feedback enable row level security;
create policy org_read on public.organizations for select to authenticated using(public.member_role(id) is not null);
create policy membership_read on public.memberships for select to authenticated using(user_id=auth.uid() or public.member_role(organization_id)='admin');
create policy stages_read on public.stages for select to authenticated using(public.member_role(organization_id) is not null);
create policy stages_admin on public.stages for all to authenticated using(public.member_role(organization_id)='admin') with check(public.member_role(organization_id)='admin');
create policy company_read on public.companies for select to authenticated using(public.member_role(organization_id) is not null);
create policy company_insert on public.companies for insert to authenticated with check(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid()));
create policy company_update on public.companies for update to authenticated using(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid())) with check(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid()));
create policy opportunity_read on public.opportunities for select to authenticated using(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid()));
create policy opportunity_insert on public.opportunities for insert to authenticated with check(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid()));
create policy opportunity_update on public.opportunities for update to authenticated using(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid())) with check(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid()));
create policy activity_read on public.activities for select to authenticated using(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid()));
create policy activity_insert on public.activities for insert to authenticated with check((public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid())) and exists(select 1 from public.opportunities o where o.organization_id=activities.organization_id and o.id=activities.opportunity_id));
create policy activity_update on public.activities for update to authenticated using(public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid())) with check((public.member_role(organization_id)='admin' or (public.member_role(organization_id)='commercial' and owner_id=auth.uid())) and exists(select 1 from public.opportunities o where o.organization_id=activities.organization_id and o.id=activities.opportunity_id));
create policy feedback_insert on public.feedback for insert to authenticated with check(public.member_role(organization_id) is not null and author_id=auth.uid());
create policy feedback_read on public.feedback for select to authenticated using(public.member_role(organization_id)='admin' or (public.member_role(organization_id) is not null and author_id=auth.uid()));
-- Prevent moving existing records to another tenant, including for administrators.
create function public.immutable_org() returns trigger language plpgsql set search_path='' as $$ begin if new.organization_id<>old.organization_id then raise exception 'Organization cannot change'; end if; return new; end $$;
create trigger company_org before update on public.companies for each row execute function public.immutable_org();
create trigger opportunity_org before update on public.opportunities for each row execute function public.immutable_org();
create trigger activity_org before update on public.activities for each row execute function public.immutable_org();
create function public.record_call(org uuid, opportunity uuid, note text, followup_title text, followup_at timestamptz, request uuid) returns void language plpgsql security invoker set search_path='' as $$ begin
 if length(trim(followup_title))=0 or followup_at is null or request is null then raise exception 'Follow-up required'; end if;
 insert into public.activities(organization_id,opportunity_id,kind,title,notes,due_at,completed_at,request_id) values(org,opportunity,'call','Llamada realizada',note,now(),now(),request) on conflict(organization_id,request_id,kind) do nothing;
 insert into public.activities(organization_id,opportunity_id,kind,title,due_at,request_id) values(org,opportunity,'followup',followup_title,followup_at,request) on conflict(organization_id,request_id,kind) do nothing;
end $$;
revoke all on function public.record_call(uuid,uuid,text,text,timestamptz,uuid) from public;
grant execute on function public.record_call(uuid,uuid,text,text,timestamptz,uuid) to authenticated;
grant usage on schema public to authenticated;
grant select on public.organizations,public.memberships to authenticated;
grant select,insert,update on public.companies,public.opportunities,public.activities,public.stages to authenticated;
grant select,insert on public.feedback to authenticated;
create table public.opportunity_stage_history(id uuid primary key default gen_random_uuid(), organization_id uuid not null, opportunity_id uuid not null, previous_stage_id uuid, stage_id uuid not null, author_id uuid not null default auth.uid(), created_at timestamptz not null default now(), foreign key(organization_id,opportunity_id) references public.opportunities(organization_id,id), foreign key(organization_id,stage_id) references public.stages(organization_id,id), foreign key(organization_id,previous_stage_id) references public.stages(organization_id,id));
alter table public.opportunity_stage_history enable row level security;
create policy history_read on public.opportunity_stage_history for select to authenticated using(exists(select 1 from public.opportunities o where o.organization_id=opportunity_stage_history.organization_id and o.id=opportunity_stage_history.opportunity_id));
grant select on public.opportunity_stage_history to authenticated;
create function public.log_stage() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if tg_op='INSERT' then insert into public.opportunity_stage_history(organization_id,opportunity_id,stage_id) values(new.organization_id,new.id,new.stage_id);
 elsif new.stage_id<>old.stage_id then insert into public.opportunity_stage_history(organization_id,opportunity_id,previous_stage_id,stage_id) values(new.organization_id,new.id,old.stage_id,new.stage_id); end if; return new;
end $$;
revoke all on function public.log_stage() from public;
create trigger opportunity_stage_log after insert or update on public.opportunities for each row execute function public.log_stage();
create function public.check_active_owner() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if not exists(select 1 from public.memberships where organization_id=new.organization_id and user_id=new.owner_id and active) then raise exception 'Owner must be an active member'; end if; return new;
end $$;
revoke all on function public.check_active_owner() from public;
create trigger company_owner before insert or update on public.companies for each row execute function public.check_active_owner();
create trigger opportunity_owner before insert or update on public.opportunities for each row execute function public.check_active_owner();
create trigger activity_owner before insert or update on public.activities for each row execute function public.check_active_owner();
-- Explicit privileges: hosted Supabase defaults can otherwise grant more than intended.
revoke all on public.organizations,public.memberships,public.companies,public.stages,public.opportunities,public.activities,public.feedback,public.opportunity_stage_history from anon;
